// ===========================================================================
// CASAGENCIA · LIBRERIA COMUN DEL ASISTENTE TELEFONICO
// ---------------------------------------------------------------------------
// Este bloque se inyecta automaticamente al principio de los nodos Code de
// los workflows BuscarDisponibilidadCalendario, ConfirmarCitaCalendario y
// BuscarCitaPorTelefono.
//
// NO editar a mano dentro de n8n: editar este fichero y volver a desplegar
// con  python3 n8n/casagencia/build_workflows.py --deploy
// ===========================================================================

const ZONA = 'Europe/Madrid';

// --- Horario de oficina de cada asesora ------------------------------------
// La visita dura 1 hora y tiene que caber ENTERA dentro de un bloque.
const HORARIOS = {
  Carmen: { lv: [['09:30', '14:00'], ['16:00', '19:30']], sab: [['10:00', '14:00']], dom: null },
  Gisela: { lv: [['09:00', '14:00'], ['16:00', '19:00']], sab: null,                 dom: null }
};

// --- Festivos ---------------------------------------------------------------
// GUARDAFUEGOS: no depende de que la comercial bloquee nada en su calendario.
// TODOS  = festivos nacionales y de la Comunitat Valenciana (fecha fija).
// BN/OR/CS/VR = fiestas locales de cada zona. RELLENAR CADA ANO.
const FESTIVOS = {
  TODOS: [
    // 2026: calendario laboral de la Comunitat Valenciana (los dos PDFs de
    // Castellon y Benicassim que mando el cliente traen los mismos)
    '2026-01-01', // Ano Nuevo
    '2026-01-06', // Reyes
    '2026-03-19', // San Jose
    '2026-04-03', // Viernes Santo
    '2026-04-06', // Lunes de Pascua (autonomica)
    '2026-05-01', // Fiesta del Trabajo
    '2026-06-24', // San Juan (autonomica)
    '2026-08-15', // Asuncion
    '2026-10-09', // Dia de la Comunitat Valenciana
    '2026-10-12', // Fiesta Nacional
    '2026-11-01', // Todos los Santos
    '2026-12-06', // Constitucion
    '2026-12-08', // Inmaculada
    '2026-12-25', // Navidad
    // Las 12 fiestas de la Comunitat Valenciana de 2027, aprobadas por la
    // Generalitat. OJO: las tres de marzo son MOVIBLES (dependen de la Pascua),
    // asi que cada ano hay que volver a mirarlas; no vale copiar las del ano
    // anterior. El 15 de agosto de 2027 cae en domingo y no esta en la lista
    // oficial, por eso no aparece aqui.
    '2027-01-01', '2027-01-06',
    '2027-03-19',  // San Jose
    '2027-03-26',  // Viernes Santo
    '2027-03-29',  // Lunes de Pascua
    '2027-05-01',
    '2027-10-09', '2027-10-12', '2027-11-01', '2027-12-06', '2027-12-08', '2027-12-25'
  ],
  // Fiestas LOCALES (calendario laboral 2026). RELLENAR CADA ANO.
  // Se reparten por asesora, no por municipio: si la oficina de Benicassim
  // cierra, Carmen no ensena nada (ni en Benicassim ni en Oropesa), y lo mismo
  // con Gisela y Castellon.
  BN: ['2026-01-17', '2026-09-22'], // Benicassim: San Antonio Abad y Santo Tomas de Villanueva
  OR: ['2026-01-17', '2026-09-22'], // Oropesa    -> Carmen, misma oficina que Benicassim
  CS: ['2026-03-09', '2026-06-29'], // Castellon: lunes de Magdalena y San Pedro
  VR: ['2026-03-09', '2026-06-29']  // Vila-real  -> Gisela, misma oficina que Castellon
};

// --- Routing de asesora (ARREGLO #7: mapeo explicito, sin fallback silencioso)
const ASESORA_POR_PREFIJO = { BN: 'Carmen', OR: 'Carmen', CS: 'Gisela', VR: 'Gisela' };
const CALENDARIO_POR_ASESORA = {
  Carmen: 'carmen@casagencia.com',
  Gisela: 'gisela@casagencia.com'
};
const CALENDARIO_POR_DEFECTO = 'gisela@casagencia.com'; // solo para que el nodo no reviente

// --- Titulos de eventos de dia completo que SI bloquean el dia (ARREGLO #8) --
const RE_DIA_BLOQUEANTE = /vacacion|vacanc|baja|festiv|cerrad|ausent|no disponible|libranza|asuntos propios/i;

// ---------------------------------------------------------------------------
// Telefonos (ARREGLO #12)
// ---------------------------------------------------------------------------
function normalizarTelefono(raw) {
  let s = String(raw ?? '').trim();
  const teniaMas = s.startsWith('+');
  s = s.replace(/\D/g, '');
  if (!teniaMas && s.startsWith('00')) s = s.slice(2);
  if (/^[6789]\d{8}$/.test(s)) s = '34' + s;          // movil/fijo espanol sin prefijo
  const nacional = s.startsWith('34') ? s.slice(2) : s;
  return {
    e164: s ? '+' + s : '',
    nacional,
    digitos: s,
    valido: s.length >= 8 && s.length <= 15,
    original: String(raw ?? '')
  };
}

// ---------------------------------------------------------------------------
// Referencias y asesora
// ---------------------------------------------------------------------------
function prefijoDeReferencia(ref) {
  const m = String(ref ?? '').toUpperCase().match(/[A-Z]{2}/);
  return m ? m[0] : '';
}

function resolverAsesora(ref) {
  const prefijo = prefijoDeReferencia(ref);
  const asesora = ASESORA_POR_PREFIJO[prefijo] || null;
  return {
    prefijo,
    asesora,
    conocida: !!asesora,
    calendario: asesora ? CALENDARIO_POR_ASESORA[asesora] : CALENDARIO_POR_DEFECTO
  };
}

// ---------------------------------------------------------------------------
// Alquiler: NO se agenda visita (peticion de Casagencia, sept. 2026)
// ---------------------------------------------------------------------------
// El mercado de alquiler esta muy tensionado y la mitad de los interesados no
// pasa la criba de la asesora. Si Sara agendase todas las visitas, el calendario
// se llenaria de citas que luego hay que deshacer. Asi que en alquiler Sara
// cualifica al cliente y pasa el aviso: la asesora llama y agenda ella.
//
// Las referencias de alquiler acaban en -A y las de venta en -V, pero hay algun
// caso suelto (un traspaso de local marcado como alquiler con referencia -V).
// Por eso basta con que CUALQUIERA de las dos senales diga alquiler.
function esPeticionAlquiler(referencia, tipoTransaccion) {
  const t = String(tipoTransaccion ?? '').toLowerCase();
  if (t.includes('alquiler') || t.includes('traspaso') || t.includes('rent')) return true;
  return /-A$/i.test(String(referencia ?? '').trim());
}

const MSG_ALQUILER_SIN_AGENDA =
  'En alquiler NO se agenda la visita desde aqui. Explicale al cliente con naturalidad que, ' +
  'por la cantidad de solicitudes que hay, es la asesora de la zona quien organiza las visitas ' +
  'de alquiler y le va a llamar para concretarla. Antes de despedirte, hazle las preguntas de ' +
  'cualificacion de alquiler y registra el aviso con registrarMensaje.';

// ---------------------------------------------------------------------------
// Horario / festivos
// ---------------------------------------------------------------------------
function esFestivo(fecha, prefijo) {
  const lista = [].concat(FESTIVOS.TODOS || [], FESTIVOS[prefijo] || []);
  return lista.includes(fecha);
}

function bloquesDelDia(fecha, asesora) {
  const h = HORARIOS[asesora] || HORARIOS.Gisela;
  const wd = DateTime.fromFormat(fecha, 'yyyy-MM-dd', { zone: ZONA }).weekday;
  if (wd === 7) return h.dom;
  if (wd === 6) return h.sab;
  return h.lv;
}

// Devuelve { valido, motivo } para una fecha+hora concretas.
// motivo: ok | formato | pasado | cerrado | festivo | fuera_horario
function validarFranja(fecha, hora, asesora, prefijo, ahora) {
  const ini = DateTime.fromFormat(`${fecha} ${hora}`, 'yyyy-MM-dd HH:mm', { zone: ZONA });
  if (!ini.isValid) return { valido: false, motivo: 'formato' };
  if (ini < ahora) return { valido: false, motivo: 'pasado' };
  if (esFestivo(fecha, prefijo)) return { valido: false, motivo: 'festivo' };

  const bloques = bloquesDelDia(fecha, asesora);
  if (!bloques || !bloques.length) return { valido: false, motivo: 'cerrado' };

  const fin = ini.plus({ hours: 1 });
  const cabe = bloques.some(([a, b]) => {
    const ba = DateTime.fromFormat(`${fecha} ${a}`, 'yyyy-MM-dd HH:mm', { zone: ZONA });
    const bb = DateTime.fromFormat(`${fecha} ${b}`, 'yyyy-MM-dd HH:mm', { zone: ZONA });
    return ini >= ba && fin <= bb;
  });
  return cabe ? { valido: true, motivo: 'ok' } : { valido: false, motivo: 'fuera_horario' };
}

// ---------------------------------------------------------------------------
// Ocupacion del calendario (ARREGLO #8)
// ---------------------------------------------------------------------------
// Un evento de dia completo (cumpleanos, recordatorio, calendario de festivos
// importado...) ya NO borra el dia entero. Solo bloquea si su titulo indica
// ausencia real. Tambien se respeta transparency='transparent' (marcado Libre).
function rangosOcupados(items) {
  const out = [];
  for (const it of items) {
    const j = (it && it.json) ? it.json : it;
    if (!j || !j.start) continue;
    if (j.status === 'cancelled') continue;
    if (j.transparency === 'transparent') continue;

    if (!j.start.dateTime) {
      if (!RE_DIA_BLOQUEANTE.test(String(j.summary || ''))) continue; // no bloquea
      const d0 = DateTime.fromISO(j.start.date, { zone: ZONA }).startOf('day');
      const d1 = j.end && j.end.date
        ? DateTime.fromISO(j.end.date, { zone: ZONA }).startOf('day')
        : d0.plus({ days: 1 });
      out.push({ start: d0, end: d1, titulo: j.summary || '', diaCompleto: true });
      continue;
    }

    const s = DateTime.fromISO(j.start.dateTime, { zone: ZONA });
    const e = j.end && j.end.dateTime
      ? DateTime.fromISO(j.end.dateTime, { zone: ZONA })
      : s.plus({ hours: 1 });
    out.push({ start: s, end: e, titulo: j.summary || '', diaCompleto: false });
  }
  return out;
}

function estaLibre(fecha, hora, ocupados) {
  const ini = DateTime.fromFormat(`${fecha} ${hora}`, 'yyyy-MM-dd HH:mm', { zone: ZONA });
  const fin = ini.plus({ hours: 1 });
  return !ocupados.some(o => ini < o.end && fin > o.start);
}

// Huecos validos de un dia (respeta horario, festivos y ocupacion)
function huecosDelDia(fecha, asesora, prefijo, ocupados, ahora) {
  if (esFestivo(fecha, prefijo)) return [];
  const bloques = bloquesDelDia(fecha, asesora);
  if (!bloques || !bloques.length) return [];
  const huecos = [];
  for (const [a, b] of bloques) {
    let cursor = DateTime.fromFormat(`${fecha} ${a}`, 'yyyy-MM-dd HH:mm', { zone: ZONA });
    const finBloque = DateTime.fromFormat(`${fecha} ${b}`, 'yyyy-MM-dd HH:mm', { zone: ZONA });
    while (cursor.plus({ hours: 1 }) <= finBloque) {
      if (cursor >= ahora && estaLibre(fecha, cursor.toFormat('HH:mm'), ocupados)) {
        huecos.push(cursor.toFormat('HH:mm'));
      }
      cursor = cursor.plus({ minutes: 30 });
    }
  }
  return huecos;
}

const DIAS = ['', 'lunes', 'martes', 'miercoles', 'jueves', 'viernes', 'sabado', 'domingo'];
const MESES = ['', 'enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio',
               'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];
function nombreDia(fecha) {
  const d = DateTime.fromFormat(fecha, 'yyyy-MM-dd', { zone: ZONA });
  if (!d.isValid) return fecha;
  return `${DIAS[d.weekday]} ${d.day} de ${MESES[d.month]}`;
}
// ======================= FIN LIBRERIA COMUN ================================


// buscarInmuebles · FiltrarYFormatear
// Filtra la hoja Inmuebles con lo que manda Retell y le devuelve el texto para
// leerlo en la llamada. Igual que en WhatsApp:
//  - Alquiler de LARGA DURACION (todo el ano) o TEMPORAL (por meses de invierno):
//    lo dice eGO (wa_cartera.modalidad, nodo ModalidadCartera) y, si no, la
//    descripcion.
//  - El presupuesto (precio_max) no es excluyente: se ensena tambien lo que se
//    pasa hasta un 30 %, marcado POR ENCIMA DE SU PRESUPUESTO.
//  - Por defecto solo viviendas: a quien busca casa no se le ofrecen locales ni
//    garajes (antes salian si decia que le daban igual las habitaciones).
// Retell manda los datos sueltos (args_at_root); si llegan dentro de "args", tambien.
const peticion = ($('Webhook').first().json.body) ?? {};
const body = (peticion.args && typeof peticion.args === 'object') ? peticion.args : peticion;

const plano = (s) => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();
const aNumero = (v) => {
  if (typeof v === 'number') return v;
  const s = String(v ?? '').replace(/[^\d.,]/g, '').replace(/\.(?=\d{3}(\D|$))/g, '').replace(',', '.');
  const n = parseFloat(s);
  return Number.isFinite(n) ? n : 0;
};

// Igual que modalidadAlquiler de wa/cartera.js (los tests comprueban que no se separen)
function modalidadPorDescripcion(descripcion) {
  const d = plano(descripcion);
  if (/temporada|temporal|no vacacional|por paquete|de (septiembre|octubre|noviembre) (a|hasta)|hasta (final de )?(mayo|junio)/.test(d)) return 'temporal';
  if (/alquiler anual|larga duracion|(alquiler|apartamento|piso|vivienda|casa|vivir) para todo el ano/.test(d)) return 'larga_duracion';
  if (/invierno/.test(d)) return 'temporal';
  return '';
}
const MODALIDAD_HABLADA = {
  larga_duracion: 'alquiler de larga duración, para todo el año',
  temporal: 'alquiler temporal, por meses de invierno, no todo el año',
};

// eGO: ref -> modalidad. Si la base de datos falla, se tira de la descripcion.
let deEgo = [];
try { deEgo = $('ModalidadCartera').all().map(i => i.json); } catch (e) { deEgo = []; }
const modalidadEgo = new Map(deEgo.filter(r => r && r.ref && r.modalidad)
  .map(r => [String(r.ref).trim().toUpperCase(), String(r.modalidad)]));

const filas = $('BuscarInmuebles').all().map(i => i.json).filter(r => r && r.ref).map(r => {
  const operacion = plano(r.tipo_transaccion);
  return {
    ...r,
    ref: String(r.ref).trim(),
    precio: aNumero(r.precio),
    habitaciones: aNumero(r.habitaciones),
    operacion,
    modalidad: operacion.includes('alquil')
      ? (modalidadEgo.get(String(r.ref).trim().toUpperCase()) || modalidadPorDescripcion(r.descripcion)) : '',
  };
});

const municipio = plano(body.municipio);
const operacion = plano(body.operacion);
const hab = aNumero(body.habitaciones);
const pmin = aNumero(body.precio_min);
const pmax = aNumero(body.precio_max);
const mq = plano(body.modalidad);
const modalidad = !operacion.includes('alquil') ? ''
  : /larga|anual|todo el ano|permanente|indefinid/.test(mq) ? 'larga_duracion'
  : /tempor|invierno|meses/.test(mq) ? 'temporal' : '';

// Que busca. Sin "tipo" (herramienta antigua) se buscan viviendas y, si no hay
// ninguna, cualquier cosa, como en WhatsApp.
const TIPOS = {
  vivienda: /apartamento|piso|chalet|villa|duplex|town house|village house|casa|estudio|ground floor|atico|bungalow|adosad|planta baja|flat|penthouse/,
  local: /local|comercial|bar|restaurant|oficina|office|nave|negocio/,
  terreno: /terreno|parcela|solar|suelo|land/,
  garaje: /garaje|garage|parking|plaza|trastero|storage/,
};
const tq = plano(body.tipo);
const tipo = TIPOS[tq] ? tq : 'vivienda';
let conTipo = true;

const encaja = (r, techo, conModalidad = true) =>
  (!conTipo || TIPOS[tipo].test(plano(r.tipo_inmueble))) &&
  r.habitaciones >= hab &&
  plano(r.municipio).includes(municipio) &&
  r.operacion.includes(operacion) &&
  r.precio >= pmin &&
  (!techo || r.precio <= techo) &&
  (!conModalidad || !modalidad || r.modalidad === modalidad);

// Presupuesto: hasta un 30 % por encima. Si ni asi hay nada, los mas baratos que
// haya. Si salen menos de 3, se completa con los siguientes hasta el doble (si dice
// 800 y hay de 1.000 y 1.100, se le ensenan; uno de 5.500, no).
const tope = pmax ? Math.round(pmax * 1.3) : 0;
function seleccionar() {
  let lista = filas.filter(r => encaja(r, tope));
  let sinTope = false;
  if (!lista.length && pmax) {
    lista = filas.filter(r => encaja(r, 0));
    sinTope = lista.length > 0;
  }
  if (pmax && !sinTope && lista.length && lista.length < 3) {
    const ya = new Set(lista.map(r => r.ref));
    lista = lista.concat(filas.filter(r => !ya.has(r.ref) && encaja(r, pmax * 2))
      .sort((a, b) => a.precio - b.precio).slice(0, 3 - lista.length));
  }
  return { lista, sinTope };
}
let { lista, sinTope } = seleccionar();
if (!lista.length && !TIPOS[tq]) {
  conTipo = false;
  ({ lista, sinTope } = seleccionar());
}
for (const r of lista) r.encima = !!pmax && r.precio > pmax;

if (lista.length === 0) {
  let texto = 'No he encontrado inmuebles con esos criterios de búsqueda.';
  if (modalidad) {
    const otra = modalidad === 'temporal' ? 'larga_duracion' : 'temporal';
    const otras = filas.filter(r => encaja(r, 0, false) && r.modalidad === otra);
    texto = `No hay ningún ${MODALIDAD_HABLADA[modalidad].split(',')[0]} con esos criterios.` + (otras.length
      ? ` Sí hay ${otras.length} de ${MODALIDAD_HABLADA[otra]}: díselo por si le interesa, dejando claro que no es lo que busca.`
      : '');
  }
  return [{ json: { result: texto + ' No inventes inmuebles: ofrécele cambiar el municipio o las habitaciones, o que la asesora le avise si entra algo.' } }];
}

// Orden: con presupuesto, primero los que caben y luego lo mas cercano a lo que
// dijo; sin presupuesto, de menor a mayor precio. Los que no tienen precio, al final.
const distancia = (r) => r.precio ? Math.abs(r.precio - pmax) : Infinity;
const ordenados = [...lista].sort((a, b) => pmax
  ? (a.encima - b.encima) || (distancia(a) - distancia(b))
  : (a.precio || Infinity) - (b.precio || Infinity));

// devuelve solo los 5 primeros inmuebles
const limitados = ordenados.slice(0, 5);

const opciones = limitados.map((d, i) => {
  const alquiler = d.operacion.includes('alquil');
  const precio = d.precio ? `${Number(d.precio).toLocaleString('es-ES')}€${alquiler ? ' al mes' : ''}` : 'precio a consultar';
  const habs = d.habitaciones ? `${d.habitaciones} habitaciones` : '';
  const ban = d.banos ? `${d.banos} baños` : '';
  const sup = d.superficie && d.superficie > 0 ? `${d.superficie}m²` : '';
  const zona = d.zona ? ` en ${d.zona}` : '';
  const detalles = [habs, ban, sup].filter(Boolean).join(', ');
  const tipo = alquiler && MODALIDAD_HABLADA[d.modalidad] ? `, ${MODALIDAD_HABLADA[d.modalidad]}` : '';
  const encima = d.encima ? ' POR ENCIMA DE SU PRESUPUESTO.' : '';
  const caract = d.caracteristicas ? `Características: ${d.caracteristicas}.` : '';
  const desc = d.descripcion
    ? `Descripción: ${String(d.descripcion).replace(/\\r\\n|\\r|\\n|\r\n|\r|\n/g, ' ').trim()}.`
    : '';
  return `Opción ${i+1}: ${d.tipo_inmueble}${zona}${tipo}, referencia ${d.ref}, ${detalles}, ${precio}.${encima} ${caract} ${desc}`;
}).join(' | ');

const total = lista.length > 5
  ? ` He encontrado ${lista.length} en total y te muestro ${pmax ? 'los 5 que mejor encajan con su presupuesto' : 'los 5 más económicos, ordenados de menor a mayor precio'}.`
  : '';
const avisos = (sinTope
  ? ` No hay nada por debajo de ${pmax}€; estos son los más económicos que hay: díselo con el precio.` : '')
  + (!sinTope && lista.some(r => r.encima)
  ? ` Los marcados POR ENCIMA DE SU PRESUPUESTO se pasan de los ${pmax}€ que dijo: preséntalos igualmente diciendo el precio.` : '');

return [{ json: { result: `He encontrado ${lista.length} inmueble${lista.length !== 1 ? 's' : ''}.${total}${avisos} ${opciones}` } }];
